query.base:
TS metrics-gcp.cloudsql_mysql.otel-*
| WHERE resource.attributes.gcp.resource_type == "cloudsql_database"
// Per instance and minute: samples of the MySQL marker, database/up and database/instance_state. up and
// instance_state keep arriving when an outage or a stop by the owner ends the MySQL metrics, and those cases
// belong to the "Instance not serving" rule.
| STATS marker = SUM(COUNT_OVER_TIME(`metrics.cloudsql.googleapis.com/database/mysql/queries`)),
        up_samples = SUM(COUNT_OVER_TIME(`metrics.cloudsql.googleapis.com/database/up`)),
        state_samples = SUM(COUNT_OVER_TIME(`metrics.cloudsql.googleapis.com/database/instance_state`))
  BY `@timestamp` = TBUCKET(1 minute), database_id
// Newest minute with any of these samples
| STATS last_sample = MAX(`@timestamp`) WHERE marker > 0 OR up_samples > 0 OR state_samples > 0,
        marker = SUM(marker)
  BY database_id

breach.segment:
WHERE marker > 0
| EVAL minutes_since_last_sample = DATE_DIFF("minute", last_sample, NOW())
// Threshold: 20 minutes, about four times the normal 3-5 minute Cloud Monitoring delivery delay.
// Raise it if the receiver collection_interval is longer than 5 minutes.
| WHERE minutes_since_last_sample >= 20
| SORT minutes_since_last_sample DESC, database_id ASC
// Up to 1000 breaching instances per run (the ES|QL default row limit); raise it for larger fleets
| LIMIT 1000
| KEEP database_id, last_sample, minutes_since_last_sample
